// Regenerates docs/lint-rules.md from the rule registry. Run: npm run docs
const fs = require('fs');
const path = require('path');
const { LINT_RULES } = require('../out/src/core/linter/rules.js');

const groups = [
  ['YL0', 'Syntax'],
  ['YL1', 'Structure'],
  ['YL2', 'Variables'],
  ['YL3', 'Functions, regular expressions & performance'],
  ['YL4', 'Meta'],
  ['YL5', 'Outcomes'],
  ['YL6', 'Match'],
  ['YL7', 'Style'],
  ['YL8', 'Options'],
];

const lines = [
  '# Lint rules',
  '',
  '<!-- Generated by scripts/gen-lint-docs.js — do not edit by hand. -->',
  '',
  'Every diagnostic has a stable ID (`YL…`) and a name. Either can be used to change its severity in `.yaral-lint.json` or VS Code settings, or in suppression comments:',
  '',
  '```jsonc',
  '{ "rules": { "YL506": "off", "unused-placeholder": "error" } }',
  '```',
  '',
  '```yaral',
  '// yaral-lint-disable-next-line YL205',
  '$e.principal.hostname = $host',
  '',
  '$e.target.ip = $ip // yaral-lint-disable-line unused-placeholder',
  '',
  '// yaral-lint-disable YL208   (anywhere in the file: whole-file suppression)',
  '```',
  '',
  'Severities: `error`, `warning`, `info`, `hint`, `off`. The CLI exits non-zero on errors (and on warnings above `--max-warnings`).',
  '',
];
for (const [prefix, title] of groups) {
  lines.push(`## ${title}`, '', '| ID | Name | Default | Description |', '|---|---|---|---|');
  for (const r of LINT_RULES.filter((x) => x.id.startsWith(prefix))) {
    lines.push(`| <a id="${r.id.toLowerCase()}"></a>${r.id} | \`${r.name}\` | ${r.severity} | ${r.description} |`);
  }
  lines.push('');
}
fs.writeFileSync(path.join(__dirname, '..', 'docs', 'lint-rules.md'), lines.join('\n'));
console.log(`Wrote docs/lint-rules.md (${LINT_RULES.length} rules)`);
